      "numero": 1,
      "ar": "سُبْحَٰنَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِّنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَا الَّذِي بَٰرَكْنَا حَوْلَهُ لِنُرِيَهُ مِنْ ءَايَٰتِنَا إِنَّهُ هُوَ السَّمِيعُ الْبَصِيرُ",
      "translit": "Subḥāna lladhī asrā biʿabdihī laylan mina l-masjidi l-ḥarāmi ilā l-masjidi l-ʾaqṣā lladhī bāraknā ḥawlahū linuriyahū min āyātinā innahū huwa s-samīʿu l-baṣīr",
