      "translit": "Aw khalqan mimmā yakburu fī ṣudūrikum fasayaqūlūna man yuʿīdunā quli lladhī faṭarakum awwala marratin fasayunghiḍūna ilayka ruʾūsahum wayaqūlūna matā huwa qul ʿasā an yakūna qarībā",
