        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Bu, senden önce gönderdiğimiz peygamberlerimize de uyguladığımız yasadır. Sen bizim yasamızda değişiklik bulamazsın"
        }
